function summarizeQueues(samples, patterns) {
  if (!Array.isArray(samples)) throw new TypeError('samples must be an array');
  const normalized = patterns === undefined
    ? []
    : typeof patterns === 'string'
      ? [patterns]
      : Array.isArray(patterns)
        ? patterns.slice()
        : null;
  if (normalized === null || normalized.some(p => typeof p !== 'string' || p.length === 0)) {
    throw new TypeError('patterns must contain non-empty strings');
  }
  const valid = n => Number.isInteger(n) && n >= 0;
  for (const sample of samples) {
    if (!sample || typeof sample !== 'object' || Array.isArray(sample) ||
        typeof sample.name !== 'string' || sample.name.length === 0 ||
        !valid(sample.active) || !valid(sample.queued) || !valid(sample.rejected)) {
      throw new TypeError('invalid queue sample');
    }
  }
  const matches = name => normalized.length === 0 || normalized.some(pattern =>
    pattern.endsWith('*') ? name.endsWith(pattern.slice(0, -1)) : name === pattern
  );
  return samples.filter(sample => matches(sample.name)).map(sample => ({
    name: sample.name,
    active: sample.active,
    queued: sample.queued,
    rejected: sample.rejected,
    load: sample.active + sample.queued
  }));
}

module.exports = { summarizeQueues };

