'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['summarizeQueues']);
const { summarizeQueues } = api;

const samples = [
  { name: 'alpha', active: 2, queued: 3, rejected: 1 },
  { name: 'api-main', active: 0, queued: 4, rejected: 0 },
  { name: 'api-backup', active: 5, queued: 0, rejected: 2 }
];
const snapshot = structuredClone(samples);
const selected = summarizeQueues(samples, ['api*', 'api-main']);
assert.deepEqual(selected, [
  { name: 'api-main', active: 0, queued: 4, rejected: 0, load: 4 },
  { name: 'api-backup', active: 5, queued: 0, rejected: 2, load: 5 }
]);
assert.deepEqual(samples, snapshot);
assert.notStrictEqual(selected[0], samples[1]);
selected[0].active = 99;
assert.equal(samples[1].active, 0);

assert.deepEqual(summarizeQueues(samples, 'alpha'), [
  { name: 'alpha', active: 2, queued: 3, rejected: 1, load: 5 }
]);
assert.deepEqual(summarizeQueues(samples), samples.map(x => ({ ...x, load: x.active + x.queued })));
assert.deepEqual(summarizeQueues(samples, undefined), samples.map(x => ({ ...x, load: x.active + x.queued })));
assert.deepEqual(summarizeQueues(samples, []), samples.map(x => ({ ...x, load: x.active + x.queued })));
assert.deepEqual(summarizeQueues([], '*'), []);
assert.deepEqual(summarizeQueues(samples, 'missing*'), []);

for (const bad of [null, 3, {}, [1], ['ok', null]]) {
  assert.throws(() => summarizeQueues(samples, bad), TypeError);
}
for (const badSamples of [null, {}, [{ name: '', active: 0, queued: 0, rejected: 0 }], [{ name: 'x', active: -1, queued: 0, rejected: 0 }], [{ name: 'x', active: 1.5, queued: 0, rejected: 0 }], [{ name: 'x', active: 0, queued: NaN, rejected: 0 }], [{ name: 'x', active: 0, queued: 0, rejected: '0' }]]) {
  assert.throws(() => summarizeQueues(badSamples), TypeError);
}

